content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-13-health-reminder-004

=== 用户原始指令 (query.txt) ===
搞个喝水提醒卡吧，有几项能打勾，能看天气，有红色提示该喝水了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个喝水提醒卡吧，有几项能打勾，能看天气，有红色提示该喝水了",
  "size": "2x4",
  "eventCandidates": [],
  "dataModelSchema": {
    "reminder": {
      "title": {
        "type": "string",
        "description": "喝水提醒卡片标题。",
        "sampleValue": "喝水提醒"
      },
      "statusText": {
        "type": "string",
        "description": "当前喝水提醒状态提示，红色强调该喝水。",
        "sampleValue": "该喝水了"
      },
      "targetText": {
        "type": "string",
        "description": "本次建议饮水量展示文本。",
        "sampleValue": "250ml"
      },
      "nextTimeText": {
        "type": "string",
        "description": "下一次提醒时间展示文本。",
        "sampleValue": "下次 15:30"
      },
      "tasks": {
        "type": "array",
        "description": "卡片上固定展示的健康提醒勾选项。",
        "sampleValue": [
          {
            "label": "喝水",
            "checked": false
          },
          {
            "label": "吃药",
            "checked": true
          },
          {
            "label": "记录",
            "checked": false
          }
        ],
        "items": {
          "type": "object",
          "description": "单个提醒勾选项。",
          "properties": {
            "label": {
              "type": "string",
              "description": "提醒勾选项名称。",
              "sampleValue": "喝水"
            },
            "checked": {
              "type": "boolean",
              "description": "提醒勾选项是否已完成。",
              "sampleValue": false
            }
          }
        }
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县名称。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "29°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/drop_1.svg",
      "description": "水滴线性图标，适合用于饮水提醒、湿度或补水状态识别。"
    },
    {
      "src": "resources/base/media/partly_cloudy.png",
      "description": "彩色多云天气图标，适合用于当前天气摘要。"
    }
  ]
}

